#[derive(Clone, Copy, Debug, PartialEq, Eq, ValueEnum)]
enum Provider {
    None,
    Codex,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, ValueEnum)]
enum AgentTarget {
    Codex,
    Claude,
}

impl AgentTarget {
    fn label(self) -> &'static str {
        match self {
            AgentTarget::Codex => "codex",
            AgentTarget::Claude => "claude",
        }
    }

    fn skill_root(self, root: &Path) -> PathBuf {
        match self {
            AgentTarget::Codex => root.join(".agents").join("skills"),
            AgentTarget::Claude => root.join(".claude").join("skills"),
        }
    }

    fn target_tool(self) -> CommandReadiness {
        match self {
            AgentTarget::Codex => command_readiness("codex", &["--version"]),
            AgentTarget::Claude => command_readiness("claude", &["--version"]),
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, ValueEnum)]
enum ScaffoldShape {
    #[value(name = "domain-engine")]
    DomainEngine,
    #[value(name = "boundary-adapter")]
    BoundaryAdapter,
    #[value(name = "runtime-monitor")]
    RuntimeMonitor,
    Workflow,
    #[value(name = "storage-adapter")]
    StorageAdapter,
    #[value(name = "integration-adapter")]
    IntegrationAdapter,
    Composite,
}

impl ScaffoldShape {
    fn as_str(self) -> &'static str {
        match self {
            ScaffoldShape::DomainEngine => "domain-engine",
            ScaffoldShape::BoundaryAdapter => "boundary-adapter",
            ScaffoldShape::RuntimeMonitor => "runtime-monitor",
            ScaffoldShape::Workflow => "workflow",
            ScaffoldShape::StorageAdapter => "storage-adapter",
            ScaffoldShape::IntegrationAdapter => "integration-adapter",
            ScaffoldShape::Composite => "composite",
        }
    }

    fn title(self) -> &'static str {
        match self {
            ScaffoldShape::DomainEngine => "Domain Engine",
            ScaffoldShape::BoundaryAdapter => "Boundary Adapter",
            ScaffoldShape::RuntimeMonitor => "Runtime Monitor",
            ScaffoldShape::Workflow => "Workflow",
            ScaffoldShape::StorageAdapter => "Storage Adapter",
            ScaffoldShape::IntegrationAdapter => "Integration Adapter",
            ScaffoldShape::Composite => "Composite",
        }
    }

    fn purpose(self) -> &'static str {
        match self {
            ScaffoldShape::DomainEngine => {
                "pure decisions, closed variants, validated values, transition records, laws, and replay bundles"
            }
            ScaffoldShape::BoundaryAdapter => {
                "parsers, boundary validation, ports, effect adapters, and contract or boundary tests"
            }
            ScaffoldShape::RuntimeMonitor => {
                "observed inputs, derived streams or facts, trigger conditions, monitor authority, and runtime evidence"
            }
            ScaffoldShape::Workflow => {
                "commands, states, events, deadlines, compensation, and recovery evidence"
            }
            ScaffoldShape::StorageAdapter => {
                "persistence ports, failure categories, migration, and recovery evidence"
            }
            ScaffoldShape::IntegrationAdapter => {
                "external service boundaries, retries, idempotency, and reconciliation evidence"
            }
            ScaffoldShape::Composite => {
                "contained submodules, public exports, visibility boundaries, and composition evidence"
            }
        }
    }

    fn roles(self) -> &'static [&'static str] {
        match self {
            ScaffoldShape::DomainEngine => &[
                "representation",
                "commands",
                "transitions",
                "trace-replay",
                "law-evidence",
            ],
            ScaffoldShape::BoundaryAdapter => &[
                "representation",
                "parsers",
                "ports",
                "adapters",
                "boundary-evidence",
            ],
            ScaffoldShape::RuntimeMonitor => &[
                "observations",
                "derived-streams",
                "triggers",
                "supervisory-outputs",
                "runtime-evidence",
            ],
            ScaffoldShape::Workflow => &[
                "representation",
                "commands",
                "states",
                "transitions",
                "compensation",
                "recovery-evidence",
            ],
            ScaffoldShape::StorageAdapter => &[
                "representation",
                "persistence-port",
                "adapter",
                "migration",
                "recovery-evidence",
            ],
            ScaffoldShape::IntegrationAdapter => &[
                "representation",
                "external-port",
                "adapter",
                "retry-idempotency",
                "reconciliation-evidence",
            ],
            ScaffoldShape::Composite => &[
                "submodule-containment",
                "public-exports",
                "visibility-boundaries",
                "composition-evidence",
            ],
        }
    }

    fn inferred(kind: &str, profiles: &[String]) -> Self {
        if profiles.iter().any(|profile| profile == "monitor") {
            ScaffoldShape::RuntimeMonitor
        } else if profiles.iter().any(|profile| profile == "workflow") {
            ScaffoldShape::Workflow
        } else if kind.contains("adapter") || profiles.iter().any(|profile| profile == "boundary") {
            ScaffoldShape::BoundaryAdapter
        } else if kind.contains("composite") {
            ScaffoldShape::Composite
        } else {
            ScaffoldShape::DomainEngine
        }
    }

    fn from_str(value: &str) -> Option<Self> {
        match value {
            "domain-engine" => Some(ScaffoldShape::DomainEngine),
            "boundary-adapter" => Some(ScaffoldShape::BoundaryAdapter),
            "runtime-monitor" => Some(ScaffoldShape::RuntimeMonitor),
            "workflow" => Some(ScaffoldShape::Workflow),
            "storage-adapter" => Some(ScaffoldShape::StorageAdapter),
            "integration-adapter" => Some(ScaffoldShape::IntegrationAdapter),
            "composite" => Some(ScaffoldShape::Composite),
            _ => None,
        }
    }
}

fn machine_mode_for_shape(shape: ScaffoldShape) -> &'static str {
    match shape {
        ScaffoldShape::DomainEngine => "stateless-decision-machine",
        ScaffoldShape::BoundaryAdapter => "boundary-machine",
        ScaffoldShape::Workflow => "workflow-effect-machine",
        ScaffoldShape::StorageAdapter => "storage-machine",
        ScaffoldShape::IntegrationAdapter => "integration-machine",
        ScaffoldShape::RuntimeMonitor => "projection-machine",
        ScaffoldShape::Composite => "stateful-transition-machine",
    }
}

fn starter_states_for_shape(shape: ScaffoldShape) -> Vec<String> {
    match shape {
        ScaffoldShape::DomainEngine => vec!["Ready"],
        ScaffoldShape::BoundaryAdapter => vec!["AwaitingInput", "Completed", "Rejected"],
        ScaffoldShape::Workflow => vec!["NotStarted", "WaitingForEffect", "Completed", "Failed"],
        ScaffoldShape::StorageAdapter | ScaffoldShape::IntegrationAdapter => {
            vec!["Ready", "WaitingForEffect", "Completed", "Failed"]
        }
        ScaffoldShape::RuntimeMonitor => vec!["Observing", "Projected", "Rejected"],
        ScaffoldShape::Composite => vec!["Ready"],
    }
    .into_iter()
    .map(str::to_string)
    .collect()
}

