fn validate_codex_plugin_sync(root: &Path) -> Result<()> {
    let plugin_root = root.join(CODEX_PLUGIN_PATH);
    let manifest_path = plugin_root.join(".codex-plugin/plugin.json");
    let manifest_source = fs::read_to_string(&manifest_path)
        .with_context(|| format!("failed to read `{}`", manifest_path.display()))?;
    let manifest: JsonValue = serde_json::from_str(&manifest_source)
        .with_context(|| format!("failed to parse `{}`", manifest_path.display()))?;
    for field in ["name", "version", "description", "skills"] {
        if manifest.get(field).is_none() {
            bail!("Codex plugin manifest missing `{field}`");
        }
    }
    if manifest.get("skills").and_then(JsonValue::as_str) != Some("./skills/") {
        bail!("Codex plugin manifest `skills` must be `./skills/`");
    }

    for skill in CANONICAL_SKILLS {
        let canonical = root.join("skills").join(skill).join("SKILL.md");
        let packaged = plugin_root.join("skills").join(skill).join("SKILL.md");
        let canonical_source = fs::read_to_string(&canonical)
            .with_context(|| format!("failed to read `{}`", canonical.display()))?;
        let packaged_source = fs::read_to_string(&packaged)
            .with_context(|| format!("failed to read `{}`", packaged.display()))?;
        if canonical_source != packaged_source {
            bail!("Codex plugin skill `{skill}` is out of sync with canonical `skills/{skill}`");
        }
    }

    let mut packaged_skills = BTreeSet::new();
    let plugin_skills_dir = plugin_root.join("skills");
    for entry in fs::read_dir(&plugin_skills_dir)
        .with_context(|| format!("failed to read `{}`", plugin_skills_dir.display()))?
        .filter_map(Result::ok)
    {
        if entry.path().is_dir() {
            if let Some(name) = entry.file_name().to_str() {
                packaged_skills.insert(name.to_string());
            }
        }
    }
    let expected = CANONICAL_SKILLS
        .iter()
        .map(|skill| (*skill).to_string())
        .collect::<BTreeSet<_>>();
    if packaged_skills != expected {
        bail!("Codex plugin skill set does not match canonical skill set");
    }
    Ok(())
}

fn validate_embedded_skill_assets(root: &Path) -> Result<()> {
    compare_skill_file(
        &root.join("skills/README.md"),
        &root.join("tooling/rust/rms/assets/skills/README.md"),
        "embedded skills README",
    )?;
    compare_skill_file(
        &root.join("skills/README.md"),
        &root.join("integrations/codex/rms/skills/README.md"),
        "Codex plugin skills README",
    )?;
    for skill in CANONICAL_SKILLS {
        let canonical = root.join("skills").join(skill).join("SKILL.md");
        compare_skill_file(
            &canonical,
            &root
                .join("tooling/rust/rms/assets/skills")
                .join(skill)
                .join("SKILL.md"),
            &format!("embedded skill `{skill}`"),
        )?;
        compare_skill_file(
            &canonical,
            &root
                .join("integrations/codex/rms/skills")
                .join(skill)
                .join("SKILL.md"),
            &format!("Codex plugin skill `{skill}`"),
        )?;
    }
    Ok(())
}

fn compare_skill_file(canonical: &Path, copy: &Path, label: &str) -> Result<()> {
    let canonical_source = fs::read_to_string(canonical)
        .with_context(|| format!("failed to read `{}`", canonical.display()))?;
    let copy_source =
        fs::read_to_string(copy).with_context(|| format!("failed to read `{}`", copy.display()))?;
    if canonical_source != copy_source {
        bail!("{label} is out of sync with `{}`", canonical.display());
    }
    Ok(())
}

fn run_release_agent_distribution_smoke(rms_exe: &Path) -> Result<()> {
    let temp = std::env::temp_dir().join(format!(
        "rms-release-agent-{}-{}",
        std::process::id(),
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_secs())
            .unwrap_or(0)
    ));
    let project = temp.join("project");
    let marketplace = temp.join("marketplace.json");
    fs::create_dir_all(&project)
        .with_context(|| format!("failed to create `{}`", project.display()))?;
    let result = (|| -> Result<()> {
        run_release_step(
            "agent init codex",
            command_with_args(
                rms_exe,
                &["agent", "init", "--target", "codex", "--root", "."],
                &project,
            ),
        )?;
        run_release_step(
            "agent sync codex",
            command_with_args(
                rms_exe,
                &["agent", "sync", "--target", "codex", "--root", "."],
                &project,
            ),
        )?;
        run_release_step(
            "agent plugin install codex",
            command_with_args(
                rms_exe,
                &[
                    "agent",
                    "plugin",
                    "install",
                    "--target",
                    "codex",
                    "--marketplace-path",
                    marketplace.to_string_lossy().as_ref(),
                    "--skip-codex-add",
                ],
                &project,
            ),
        )?;
        run_release_step(
            "agent plugin diagnose codex",
            command_with_args(
                rms_exe,
                &[
                    "agent",
                    "plugin",
                    "diagnose",
                    "--target",
                    "codex",
                    "--marketplace-path",
                    marketplace.to_string_lossy().as_ref(),
                ],
                &project,
            ),
        )?;
        ensure_file_exists(
            &project.join(".agents/skills/implement-change/SKILL.md"),
            "temp project Codex RMS skill",
        )?;
        ensure_file_exists(&marketplace, "temp Codex marketplace")?;
        Ok(())
    })();
    let _ = fs::remove_dir_all(&temp);
    result
}

fn render_workbench_config(provider: Provider, model: Option<&str>, run_root: &Path) -> String {
    let mut out = String::new();
    out.push_str("ai:\n");
    let _ = writeln!(out, "  default_provider: {}", provider.label());
    out.push_str("  codex:\n");
    if let Some(model) = model.filter(|value| !value.trim().is_empty()) {
        let _ = writeln!(out, "    model: {}", yaml_quote(model));
    }
    out.push_str("    sandbox: read-only\n");
    out.push_str("    # Provider edits are opt-in; when needed, uncomment both lines below.\n");
    out.push_str("    # sandbox: workspace-write\n");
    out.push_str("    # write_scope: module\n");
    let _ = writeln!(
        out,
        "    # timeout_seconds: {}",
        DEFAULT_PROVIDER_TIMEOUT_SECONDS
    );
    out.push_str("runs:\n");
    let _ = writeln!(
        out,
        "  directory: {}",
        yaml_quote(&run_root.display().to_string())
    );
    out
}

fn parse_config_provider(value: &str, field: &str) -> Result<Provider> {
    match value {
        "none" => Ok(Provider::None),
        "codex" => Ok(Provider::Codex),
        other => bail!("unsupported `{field}` value `{other}`; expected `none` or `codex`"),
    }
}

fn parse_config_sandbox(value: &str, field: &str) -> Result<CodexSandbox> {
    match value {
        "read-only" => Ok(CodexSandbox::ReadOnly),
        "workspace-write" => Ok(CodexSandbox::WorkspaceWrite),
        other => bail!(
            "unsupported `{field}` value `{other}`; expected `read-only` or `workspace-write`"
        ),
    }
}

fn parse_config_write_scope(value: &str, field: &str) -> Result<ProviderWriteScope> {
    match value {
        "module" => Ok(ProviderWriteScope::Module),
        "root" => Ok(ProviderWriteScope::Root),
        other => bail!("unsupported `{field}` value `{other}`; expected `module` or `root`"),
    }
}

fn parse_config_timeout_seconds(value: u64, field: &str) -> Result<u64> {
    if value == 0 {
        bail!("unsupported `{field}` value `0`; expected a positive integer")
    }
    Ok(value)
}

