static RUST_BINDING_ADAPTER: RustBindingAdapter = RustBindingAdapter;
static SWIFT_BINDING_ADAPTER: SwiftBindingAdapter = SwiftBindingAdapter;
static JS_BINDING_ADAPTER: JsBindingAdapter = JsBindingAdapter;
static EXECUTABLE_BINDING_ADAPTER: ExecutableBindingAdapter = ExecutableBindingAdapter;

fn binding_adapter(binding: &str) -> Result<&'static dyn BindingAdapter> {
    match binding {
        "rust" => Ok(&RUST_BINDING_ADAPTER),
        "swift" => Ok(&SWIFT_BINDING_ADAPTER),
        "js" => Ok(&JS_BINDING_ADAPTER),
        "executable" => Ok(&EXECUTABLE_BINDING_ADAPTER),
        other => bail!("unsupported scaffold binding `{other}`"),
    }
}

fn realize_declared_proof_commands(implementation: &mut LoadedManifest) -> Result<()> {
    let binding = get_str(&implementation.value, &["binding"])
        .ok_or_else(|| anyhow!("implementation binding is missing `binding`"))?
        .to_string();
    let adapter = binding_adapter(&binding)?;
    let property_commands = property_targets_from_implementation(
        implementation,
        &["architecture", "reliability", "properties"],
        "property",
    )
    .into_iter()
    .chain(property_targets_from_implementation(
        implementation,
        &["architecture", "reliability", "fuzz_targets"],
        "fuzz",
    ))
    .flat_map(|target| {
        target
            .realizations
            .into_iter()
            .map(|realization| realization.command)
    })
    .collect::<BTreeSet<_>>();
    let trace_commands = trace_producers_from_implementation(implementation)
        .into_iter()
        .map(|producer| producer.command)
        .collect::<BTreeSet<_>>();
    for command in property_commands {
        if get_str(&implementation.value, &["commands", &command]).is_none() {
            set_yaml_string_path(
                &mut implementation.value,
                &["commands", &command],
                adapter.property_proof_command(),
            );
        }
    }
    for command in trace_commands {
        if get_str(&implementation.value, &["commands", &command]).is_none() {
            set_yaml_string_path(
                &mut implementation.value,
                &["commands", &command],
                adapter.trace_proof_command(),
            );
        }
    }
    adapter.realize_proof_support(implementation)
}

fn realize_capability_binding_dependency(
    boundary_path: &Path,
    domain_module: &str,
    binding: &str,
) -> Result<()> {
    let implementation_path = boundary_path.join("implementation.yaml");
    if !implementation_path.exists() {
        return Ok(());
    }
    let mut implementation = load_manifest(&implementation_path)?;
    let previous = get_string_array(&implementation.value, &["dependencies", "local_modules"]);
    let mut final_dependencies = previous.clone();
    if !final_dependencies.iter().any(|item| item == domain_module) {
        final_dependencies.push(domain_module.to_string());
    }
    binding_adapter(binding)?.realize_local_dependencies(
        &mut implementation,
        &previous,
        &final_dependencies,
    )?;
    write_yaml_manifest(&implementation)
}

fn realize_binding_dependency_metadata(
    value: &mut YamlValue,
    previous: &[String],
    final_dependencies: &[String],
    allowlist_key: &str,
    binding_name: fn(&str) -> String,
) {
    set_yaml_string_sequence_path(
        value,
        &["dependencies", "local_modules"],
        final_dependencies,
    );
    let previous_binding_names = previous
        .iter()
        .map(|name| binding_name(name))
        .collect::<BTreeSet<_>>();
    let mut allowlist = get_string_array(value, &["dependencies", allowlist_key]);
    allowlist.retain(|name| !previous_binding_names.contains(name));
    allowlist.extend(final_dependencies.iter().map(|name| binding_name(name)));
    set_yaml_string_sequence_path(
        value,
        &["dependencies", allowlist_key],
        &dedup_preserve_order(allowlist),
    );
}

fn realize_rust_path_dependencies(
    implementation: &LoadedManifest,
    previous: &[String],
    final_dependencies: &[String],
) -> Result<()> {
    let module_dir = implementation
        .path
        .parent()
        .unwrap_or_else(|| Path::new("."));
    let cargo_path = module_dir.join(
        get_str(&implementation.value, &["toolchain", "cargo_manifest"]).unwrap_or("Cargo.toml"),
    );
    if !cargo_path.exists() {
        return Ok(());
    }
    let source = fs::read_to_string(&cargo_path)
        .with_context(|| format!("failed to read `{}`", cargo_path.display()))?;
    let mut cargo: TomlValue = toml::from_str(&source)
        .with_context(|| format!("failed to parse `{}`", cargo_path.display()))?;
    let dependencies = cargo
        .as_table_mut()
        .ok_or_else(|| anyhow!("`{}` must contain a TOML table", cargo_path.display()))?
        .entry("dependencies")
        .or_insert_with(|| TomlValue::Table(toml::map::Map::new()))
        .as_table_mut()
        .ok_or_else(|| {
            anyhow!(
                "`{}` dependencies must be a TOML table",
                cargo_path.display()
            )
        })?;
    let previous_names = previous
        .iter()
        .map(|name| canonical_rust_crate_name(name))
        .collect::<BTreeSet<_>>();
    dependencies.retain(|name, _| !previous_names.contains(&canonical_rust_crate_name(name)));
    for dependency in final_dependencies {
        let provider = module_dir.parent().unwrap_or(module_dir).join(dependency);
        if !provider.join("Cargo.toml").is_file() {
            continue;
        }
        let mut declaration = toml::map::Map::new();
        declaration.insert(
            "path".to_string(),
            TomlValue::String(format!("../{dependency}")),
        );
        dependencies.insert(dependency.clone(), TomlValue::Table(declaration));
    }
    let rendered = toml::to_string_pretty(&cargo)
        .with_context(|| format!("failed to render `{}`", cargo_path.display()))?;
    fs::write(&cargo_path, rendered)
        .with_context(|| format!("failed to write `{}`", cargo_path.display()))
}

fn realize_rust_trace_proof_dependency(implementation: &LoadedManifest) -> Result<()> {
    let module_dir = implementation
        .path
        .parent()
        .unwrap_or_else(|| Path::new("."));
    let cargo_path = module_dir.join(
        get_str(&implementation.value, &["toolchain", "cargo_manifest"]).unwrap_or("Cargo.toml"),
    );
    if !cargo_path.exists() {
        return Ok(());
    }
    if rust_cargo_declares_dependency(&cargo_path, "serde_json")? {
        return Ok(());
    }
    let source = fs::read_to_string(&cargo_path)
        .with_context(|| format!("failed to read `{}`", cargo_path.display()))?;
    let mut cargo: TomlValue = toml::from_str(&source)
        .with_context(|| format!("failed to parse `{}`", cargo_path.display()))?;
    let dev_dependencies = cargo
        .as_table_mut()
        .ok_or_else(|| anyhow!("`{}` must contain a TOML table", cargo_path.display()))?
        .entry("dev-dependencies")
        .or_insert_with(|| TomlValue::Table(toml::map::Map::new()))
        .as_table_mut()
        .ok_or_else(|| {
            anyhow!(
                "`{}` dev-dependencies must be a TOML table",
                cargo_path.display()
            )
        })?;
    dev_dependencies.insert("serde_json".to_string(), TomlValue::String("1".to_string()));
    let rendered = toml::to_string_pretty(&cargo)
        .with_context(|| format!("failed to render `{}`", cargo_path.display()))?;
    fs::write(&cargo_path, rendered)
        .with_context(|| format!("failed to write `{}`", cargo_path.display()))
}

fn rust_cargo_declares_dependency(cargo_path: &Path, dependency: &str) -> Result<bool> {
    let source = fs::read_to_string(cargo_path)
        .with_context(|| format!("failed to read `{}`", cargo_path.display()))?;
    let cargo: TomlValue = toml::from_str(&source)
        .with_context(|| format!("failed to parse `{}`", cargo_path.display()))?;
    Ok(["dependencies", "dev-dependencies", "build-dependencies"]
        .iter()
        .any(|table| {
            cargo
                .get(table)
                .and_then(TomlValue::as_table)
                .is_some_and(|dependencies| dependencies.contains_key(dependency))
        }))
}

fn write_scaffold_plan_record(
    request: &AddModuleRequest,
    shape: ScaffoldShape,
    options: &PromptRunOptions,
) -> Result<()> {
    let manifest = synthetic_workbench_manifest(
        &request.root,
        &format!("scaffold-{}", request.name),
        "advisory scaffold plan",
    );
    let mut prompt = render_scaffold_plan_prompt(request, shape)?;
    if options.provider != Provider::None {
        prompt.push_str(&render_provider_execution_scope(
            &manifest,
            &request.root,
            options,
        ));
    }
    let run_dir = write_prompt_run_record(
        &manifest,
        &request.root,
        PromptKind::Design,
        Some(&format!("scaffold module {}", request.name)),
        None,
        false,
        &prompt,
        options,
    )?;
    if options.provider == Provider::Codex {
        execute_codex_provider(&request.root, &manifest, &prompt, &run_dir, options)?;
        fs::write(
            run_dir.join("scaffold-plan.status"),
            "provider response recorded as advisory evidence; deterministic scaffold remains canonical only after generated artifacts are written\n",
        )?;
    }
    eprintln!("scaffold plan run record: {}", run_dir.display());
    Ok(())
}

fn render_scaffold_plan_prompt(request: &AddModuleRequest, shape: ScaffoldShape) -> Result<String> {
    let mut out = String::new();
    writeln!(out, "# RMS Scaffold Plan Prompt")?;
    writeln!(out)?;
    writeln!(out, "Prompt: rms.design@v1")?;
    writeln!(out, "Mode: advisory scaffold planning")?;
    writeln!(out, "Module: {}", request.name)?;
    writeln!(out, "Target path: {}", request.path.display())?;
    writeln!(out, "Purpose: {}", request.purpose)?;
    writeln!(out, "Kind: {}", request.kind)?;
    writeln!(out, "Shape: {} ({})", shape.as_str(), shape.purpose())?;
    writeln!(
        out,
        "Binding: {}",
        request.binding.as_deref().unwrap_or("<none>")
    )?;
    writeln!(out)?;
    writeln!(out, "## Required Semantic Roles")?;
    for role in shape.roles() {
        writeln!(out, "- {role}")?;
    }
    writeln!(out)?;
    writeln!(out, "## Rules")?;
    writeln!(out, "- Propose language-idiomatic directories and files for these roles; do not treat names like `domain` or `types` as canonical RMS terms.")?;
    writeln!(
        out,
        "- Keep representation separate from transitions and boundary parsing."
    )?;
    writeln!(out, "- Keep external effects behind ports or adapters.")?;
    writeln!(out, "- Identify versioned artifacts and transformations, cross-module protocol automata, resource lifecycles, privileged/unsafe/foreign authority boundaries, and temporal properties before proposing binding files.")?;
    writeln!(out, "- Return advisory output only; canonical architecture must be reflected in manifests, contracts, implementation bindings, and evidence.")?;
    Ok(out)
}

