fn scaffold_declares_effect_results_by_default(shape: ScaffoldShape) -> bool {
    matches!(
        shape,
        ScaffoldShape::Workflow | ScaffoldShape::StorageAdapter | ScaffoldShape::IntegrationAdapter
    )
}

fn scaffold_declares_effects_by_default(shape: ScaffoldShape) -> bool {
    matches!(
        shape,
        ScaffoldShape::Workflow | ScaffoldShape::StorageAdapter | ScaffoldShape::IntegrationAdapter
    )
}

fn normalize_scaffold_effect_result_declarations(
    implementation_path: &Path,
    shape: ScaffoldShape,
    names: &InnerStructureNames,
) -> Result<()> {
    if scaffold_declares_effect_results_by_default(shape)
        && scaffold_declares_effects_by_default(shape)
    {
        return Ok(());
    }
    let source = fs::read_to_string(implementation_path)
        .with_context(|| format!("failed to read `{}`", implementation_path.display()))?;
    let mut value: YamlValue = serde_yaml::from_str(&source)
        .with_context(|| format!("failed to parse `{}`", implementation_path.display()))?;
    if !scaffold_declares_effects_by_default(shape) {
        set_yaml_sequence_path(
            &mut value,
            &["architecture", "machine", "effects"],
            Vec::new(),
        );
        remove_yaml_path(&mut value, &["architecture", "messages", "effect_envelope"]);
        remove_yaml_path(&mut value, &["architecture", "effects"]);
        remove_yaml_path(&mut value, &["architecture", "roles", "effect_lifecycle"]);
    }
    if !scaffold_declares_effect_results_by_default(shape) {
        set_yaml_sequence_path(
            &mut value,
            &["architecture", "machine", "effect_results"],
            Vec::new(),
        );
        remove_yaml_path(
            &mut value,
            &["architecture", "messages", "effect_result_envelope"],
        );
    }
    let mut closed_variants_to_remove = Vec::new();
    if !scaffold_declares_effects_by_default(shape) {
        closed_variants_to_remove.extend([names.effect.as_str(), names.effect_envelope.as_str()]);
    }
    if !scaffold_declares_effect_results_by_default(shape) {
        closed_variants_to_remove.extend([
            names.effect_result.as_str(),
            names.effect_result_envelope.as_str(),
            names.effect_lifecycle.as_str(),
        ]);
    }
    remove_yaml_string_values_path(
        &mut value,
        &["architecture", "representation", "closed_variants"],
        &closed_variants_to_remove,
    );
    remove_yaml_string_values_path(
        &mut value,
        &["architecture", "allowed_public_field_structs"],
        &closed_variants_to_remove,
    );
    fs::write(
        implementation_path,
        serde_yaml::to_string(&value)
            .with_context(|| format!("failed to render `{}`", implementation_path.display()))?,
    )
    .with_context(|| format!("failed to write `{}`", implementation_path.display()))
}

fn remove_yaml_string_values_path(value: &mut YamlValue, path: &[&str], remove: &[&str]) {
    let Some(sequence) = get_path_mut(value, path).and_then(YamlValue::as_sequence_mut) else {
        return;
    };
    sequence.retain(|item| {
        item.as_str()
            .is_none_or(|candidate| !remove.iter().any(|removed| removed == &candidate))
    });
}

fn normalized_profiles_for_shape(profiles: &[String], shape: ScaffoldShape) -> Vec<String> {
    let mut normalized = BTreeSet::from(["core".to_string()]);
    normalized.extend(profiles.iter().cloned());
    match shape {
        ScaffoldShape::BoundaryAdapter => {
            normalized.insert("boundary".to_string());
        }
        ScaffoldShape::RuntimeMonitor => {
            normalized.insert("monitor".to_string());
        }
        ScaffoldShape::Workflow => {
            normalized.insert("workflow".to_string());
        }
        ScaffoldShape::StorageAdapter | ScaffoldShape::IntegrationAdapter => {
            normalized.insert("boundary".to_string());
            normalized.insert("distributed".to_string());
        }
        ScaffoldShape::DomainEngine | ScaffoldShape::Composite => {}
    }
    normalized.into_iter().collect()
}

fn normalized_kind_for_shape(kind: &str, shape: ScaffoldShape) -> String {
    match shape {
        ScaffoldShape::BoundaryAdapter
        | ScaffoldShape::StorageAdapter
        | ScaffoldShape::IntegrationAdapter
            if kind == "module" =>
        {
            "adapter".to_string()
        }
        ScaffoldShape::RuntimeMonitor if kind == "module" => "monitor".to_string(),
        ScaffoldShape::Composite if kind == "module" => "composite".to_string(),
        _ => kind.to_string(),
    }
}

fn render_system_yaml(name: &str, purpose: &str, version: &str, contexts: &[String]) -> String {
    format!(
        "spec: rms/system/v0.1\n\nsystem:\n  name: {}\n  version: {}\n  purpose: {}\n\ncontexts:\n{}\n\npublic_interfaces: []\nexternal_dependencies: []\nworkflows: []\n\ninvariants: []\n\ncompatibility:\n  policy: backward-compatible-within-major\n\nglossary: GLOSSARY.md\ncontext_map: context-map.yaml\n",
        yaml_quote(name),
        yaml_quote(version),
        yaml_quote(purpose),
        yaml_string_list(contexts, 2)
    )
}

fn render_context_map_yaml(contexts: &[String]) -> String {
    let mut rendered = "spec: rms/context-map/v0.1\n\ncontexts:\n".to_string();
    for context in contexts {
        rendered.push_str(&format!(
            "  {}:\n    publishes: []\n    consumes: []\n",
            yaml_quote(context)
        ));
    }
    rendered.push_str("\nrelationships: []\n");
    rendered
}

fn render_glossary_md(name: &str) -> String {
    format!("# {name} Glossary\n\nAdd context-owned terms here.\n")
}

fn render_module_yaml(
    name: &str,
    purpose: &str,
    kind: &str,
    profiles: &[String],
    shape: Option<ScaffoldShape>,
) -> String {
    let verification_laws = match shape {
        Some(ScaffoldShape::DomainEngine | ScaffoldShape::Workflow) => {
            "  laws:\n    - verification/laws/transition_trace.md\n".to_string()
        }
        _ => "  laws: []\n".to_string(),
    };
    let verification_contracts = match shape {
        Some(
            ScaffoldShape::BoundaryAdapter
            | ScaffoldShape::StorageAdapter
            | ScaffoldShape::IntegrationAdapter,
        ) => "  contracts:\n    - verification/contracts/parser_to_domain_command.md\n".to_string(),
        Some(ScaffoldShape::Composite) => {
            "  contracts:\n    - verification/contracts/parent_export.md\n".to_string()
        }
        _ => "  contracts: []\n".to_string(),
    };
    let verification_scenarios = match shape {
        Some(ScaffoldShape::DomainEngine | ScaffoldShape::Workflow) => {
            "  scenarios:\n    - verification/scenarios/accepted_rejected.md\n".to_string()
        }
        _ => "  scenarios: []\n".to_string(),
    };
    let verification_boundaries = match shape {
        Some(
            ScaffoldShape::BoundaryAdapter
            | ScaffoldShape::StorageAdapter
            | ScaffoldShape::IntegrationAdapter,
        ) => "  boundaries:\n    - verification/boundaries/malformed_input.md\n".to_string(),
        _ => "  boundaries: []\n".to_string(),
    };
    let verification_runtime = if shape == Some(ScaffoldShape::RuntimeMonitor) {
        "  runtime:\n    - verification/runtime/trigger_cases.md\n"
    } else {
        ""
    };
    let verification_properties = match shape {
        Some(ScaffoldShape::DomainEngine | ScaffoldShape::Workflow) => {
            "  properties:\n    - verification/properties/transition_properties.md\n".to_string()
        }
        _ => String::new(),
    };
    let verification_fuzz = match shape {
        Some(
            ScaffoldShape::BoundaryAdapter
            | ScaffoldShape::StorageAdapter
            | ScaffoldShape::IntegrationAdapter,
        ) => "  fuzz:\n    - verification/fuzz/malformed_input_fuzz.md\n".to_string(),
        _ => String::new(),
    };
    let verification_traces = String::new();
    let composition = shape
        .filter(|shape| *shape == ScaffoldShape::Composite)
        .map(|_| "\ncomposition:\n  contains: []\n  exports: []\n".to_string())
        .unwrap_or_default();
    let scaffold = shape
        .map(|shape| {
            format!(
                "\nx-scaffold:\n  shape: {}\n  roles:\n{}\n",
                yaml_quote(shape.as_str()),
                yaml_string_list(
                    &shape
                        .roles()
                        .iter()
                        .map(|role| (*role).to_string())
                        .collect::<Vec<_>>(),
                    4
                )
            )
        })
        .unwrap_or_default();
    format!(
        "spec: rms/module/v0.1\n\nmodule:\n  name: {}\n  version: 0.1.0\n  kind: {}\n  purpose: {}\n\nprofiles:\n{}\n\nowns:\n  concepts: []\n  data: []\n  decisions: []\n\nprovides:\n  commands: []\n  queries: []\n  events: []\n  capabilities: []\n\nrequires:\n  modules: []\n  capabilities: []\n\ninvariants: []\n\neffects: []\n{}{}compatibility:\n  policy: backward-compatible-within-major\n\nverification:\n{}{}{}{}{}{}{}{}{}",
        yaml_quote(name),
        yaml_quote(kind),
        yaml_quote(purpose),
        yaml_string_list(profiles, 2),
        render_profile_sections(profiles),
        composition,
        verification_laws,
        verification_contracts,
        verification_scenarios,
        verification_boundaries,
        verification_traces,
        verification_runtime,
        verification_properties,
        verification_fuzz,
        scaffold
    )
}

fn render_capability_parent_module_yaml(
    name: &str,
    purpose: &str,
    public_command: &str,
    domain_child: &str,
    boundary_child: &str,
) -> String {
    format!(
        "spec: rms/module/v0.1\n\nmodule:\n  name: {}\n  version: 0.1.0\n  kind: \"composite\"\n  purpose: {}\n\nprofiles:\n  - \"core\"\n\nowns:\n  concepts:\n    - public capability surface\n    - child module composition\n  data: []\n  decisions:\n    - public export composition\n    - child visibility\n\nprovides:\n  commands:\n    - name: {}\n      contract: contracts/{}.v1.yaml\n  queries: []\n  events: []\n  capabilities: []\n\nrequires:\n  modules: []\n  capabilities: []\n\ncomposition:\n  contains:\n    - name: {}\n      visibility: internal\n      path: ../{}/module.yaml\n    - name: {}\n      visibility: internal\n      path: ../{}/module.yaml\n  exports:\n    - group: commands\n      name: {}\n      from: {}\n\ninvariants:\n  - id: public-command-is-child-backed\n    statement: The parent public command is backed by the declared boundary child and its domain dependency.\n    enforced_by: composition\n    verified_by: verification/scenarios/composed_capability.md\n\neffects: []\n\ncompatibility:\n  policy: backward-compatible-within-major\n\nverification:\n  laws: []\n  contracts:\n    - verification/contracts/parent_export.md\n    - verification/contracts/{}.md\n  scenarios:\n    - verification/scenarios/composed_capability.md\n  boundaries: []\n\nx-scaffold:\n  shape: \"composite\"\n  roles:\n{}\n",
        yaml_quote(name),
        yaml_quote(purpose),
        yaml_quote(public_command),
        contract_file_stem(public_command),
        yaml_quote(domain_child),
        domain_child,
        yaml_quote(boundary_child),
        boundary_child,
        yaml_quote(public_command),
        yaml_quote(boundary_child),
        contract_file_stem(public_command),
        yaml_string_list(
            &ScaffoldShape::Composite
                .roles()
                .iter()
                .map(|role| (*role).to_string())
                .collect::<Vec<_>>(),
            4,
        )
    )
    .replace(
        "    enforced_by: composition\n",
        "    authority: composition\n    enforced_by: composition\n",
    )
}

fn render_capability_domain_module_yaml(name: &str, domain_command: &str) -> String {
    strip_unrecorded_trace_evidence(format!(
        "spec: rms/module/v0.1\n\nmodule:\n  name: {}\n  version: 0.1.0\n  kind: \"library\"\n  purpose: \"Own pure capability decisions, validated values, and transition evidence.\"\n\nprofiles:\n  - \"core\"\n\nowns:\n  concepts:\n    - domain command\n    - transition outcome\n  data: []\n  decisions:\n    - command acceptance\n    - command rejection\n\nprovides:\n  commands:\n    - name: {}\n      contract: contracts/{}.v1.yaml\n  queries: []\n  events: []\n  capabilities:\n    - name: {}\n      contract: contracts/{}.v1.yaml\n\nrequires:\n  modules: []\n  capabilities: []\n\ninvariants: []\n\neffects: []\n\ncompatibility:\n  policy: backward-compatible-within-major\n\nverification:\n  laws:\n    - verification/laws/transition_trace.md\n  contracts:\n    - verification/contracts/{}.md\n  scenarios:\n    - verification/scenarios/accepted_rejected.md\n    - verification/scenarios/reusable_package.md\n  boundaries: []\n  traces:\n    - verification/traces/transition_trace.yaml\n  properties:\n    - verification/properties/transition_properties.md\n\nx-rms:\n  reusable: true\n\nx-scaffold:\n  shape: \"domain-engine\"\n  roles:\n{}\n",
        yaml_quote(name),
        yaml_quote(domain_command),
        contract_file_stem(domain_command),
        yaml_quote(domain_command),
        contract_file_stem(domain_command),
        contract_file_stem(domain_command),
        yaml_string_list(
            &ScaffoldShape::DomainEngine
                .roles()
                .iter()
                .map(|role| (*role).to_string())
                .collect::<Vec<_>>(),
            4,
        )
    ))
}

fn render_capability_boundary_module_yaml(
    name: &str,
    public_command: &str,
    domain_child: &str,
    domain_command: &str,
) -> String {
    strip_unrecorded_trace_evidence(format!(
        "spec: rms/module/v0.1\n\nmodule:\n  name: {}\n  version: 0.1.0\n  kind: \"adapter\"\n  purpose: \"Adapt untrusted input and effects to the pure domain child.\"\n\nprofiles:\n  - \"boundary\"\n  - \"core\"\n\nowns:\n  concepts:\n    - boundary input\n    - parsed domain command\n    - domain child port\n  data: []\n  decisions:\n    - boundary input parsing\n    - malformed input rejection\n    - domain command delegation\n\nprovides:\n  commands:\n    - name: {}\n      contract: contracts/{}.v1.yaml\n  queries: []\n  events: []\n  capabilities: []\n\nrequires:\n  modules:\n    - name: {}\n  capabilities:\n    - name: {}\n      contract: contracts/{}.v1.yaml\n\ninvariants: []\n\neffects:\n  - name: local-boundary-io\n    kind: local-ui\n\nboundary:\n  trust_boundary: generated-boundary-adapter\n  inputs: []\n  outputs: []\n  validation:\n    - Reject malformed input before domain delegation.\n\ncompatibility:\n  policy: backward-compatible-within-major\n\nverification:\n  laws: []\n  contracts:\n    - verification/contracts/{}.md\n    - verification/contracts/{}-dependency.md\n    - verification/contracts/parser_to_domain_command.md\n  scenarios: []\n  boundaries:\n    - verification/boundaries/malformed_input.md\n  traces:\n    - verification/traces/boundary_parse.yaml\n    - verification/traces/malformed_input_trace.yaml\n  fuzz:\n    - verification/fuzz/malformed_input_fuzz.md\n\nx-scaffold:\n  shape: \"boundary-adapter\"\n  roles:\n{}\n",
        yaml_quote(name),
        yaml_quote(public_command),
        contract_file_stem(public_command),
        yaml_quote(domain_child),
        yaml_quote(domain_command),
        contract_file_stem(domain_command),
        contract_file_stem(public_command),
        contract_file_stem(domain_command),
        yaml_string_list(
            &ScaffoldShape::BoundaryAdapter
                .roles()
                .iter()
                .map(|role| (*role).to_string())
                .collect::<Vec<_>>(),
            4,
        )
    ))
}

fn strip_unrecorded_trace_evidence(rendered: String) -> String {
    rendered
        .replace(
            "  boundaries: []\n  traces:\n    - verification/traces/transition_trace.yaml\n  properties:\n",
            "  boundaries: []\n  properties:\n",
        )
        .replace(
            "  traces:\n    - verification/traces/boundary_parse.yaml\n    - verification/traces/malformed_input_trace.yaml\n  fuzz:\n",
            "  fuzz:\n",
        )
}

fn render_capability_contract(name: &str, meaning: &str) -> String {
    format!(
        "spec: rms/contract/v0.1\nname: {}\nversion: 1\nkind: command\nmeaning: {}\npreconditions:\n  - id: valid-request\n    statement: The caller supplies input accepted by this command boundary.\npostconditions:\n  - id: explicit-outcome\n    statement: The command returns an accepted result or an explicit rejection.\nfailure_categories:\n  - id: rejected-request\n    statement: The request is rejected by boundary validation or domain rules.\ncompatibility:\n  policy: backward-compatible-within-major\nx-rms:\n  scaffold: true\n",
        yaml_quote(name),
        yaml_quote(meaning),
    )
}

fn render_capability_contract_evidence(
    module_name: &str,
    command: &str,
    contract_path: &str,
    backed_by: Option<&str>,
) -> String {
    let backing_line = backed_by
        .map(|module| {
            format!(
                "- `{}` is backed by `{}` through declared RMS composition or dependency.\n",
                markdown_inline(command),
                markdown_inline(module)
            )
        })
        .unwrap_or_default();
    format!(
        "# Contract Evidence: {command}\n\nPromise:\n\n- Module `{module}` publishes `{command}` through `{contract_path}`.\n{backing_line}- Expected failures are returned as explicit rejections instead of hidden throws or implicit states.\n\nCommand/tool:\n\n- `rms verify <module.yaml|implementation.yaml>` verifies the command against declared module structure.\n- `rms compose --root <system-root>` checks provider/consumer compatibility when the command crosses module boundaries.\n\nExpected result:\n\n- `{command}` has a matching public contract artifact.\n- Accepted and rejected paths are covered by the module's declared scenario or trace evidence.\n\nSource revision: recorded by git commit or strict audit provenance before production use.\n",
        command = markdown_inline(command),
        module = markdown_inline(module_name),
        contract_path = markdown_inline(contract_path),
        backing_line = backing_line,
    )
}

fn render_reusable_package_evidence(module_name: &str, capability: &str) -> String {
    format!(
        "# Scenario Evidence: reusable package\n\nPromise:\n\n- Module `{module}` is reusable through RMS capability `{capability}` and its declared public facade.\n- Consumers depend on `provides.capabilities[]` and the public contract, not private representation, parser, adapter, or transition role files.\n- RMS semantic packages are the portable reuse artifact; native package files are optional binding evidence only.\n\nCommand/tool:\n\n- `rms package module.yaml` assembles, verifies, and records the canonical RMS package result.\n- `rms verify-package dist/{module}-0.1.0.rms` can independently verify package metadata, checksums, manifests, implementation binding, and conformance report.\n- `rms compose --root <system-root>` verifies consumer `requires.capabilities[]` compatibility against this provider capability.\n\nExpected result:\n\n- The package contains `module.yaml`, contracts, implementation binding when present, declared public facade, evidence, conformance report, source revision, and checksums.\n- Consumer modules import only the declared public facade or call through contract-shaped entrypoints.\n- Expected-result prose alone is not production proof; `rms package` appends the exact recorded result after successful verification.\n\nSource revision: recorded by git commit or strict audit provenance before production use.\n",
        module = markdown_inline(module_name),
        capability = markdown_inline(capability),
    )
}

fn render_capability_dependency_contract_evidence(
    module_name: &str,
    provider_module: &str,
    required_command: &str,
    required_contract_path: &str,
) -> String {
    format!(
        "# Dependency Contract Evidence: {required_command}\n\nPromise:\n\n- Module `{module}` depends on `{provider}` through required capability `{required_command}`.\n- The required contract is `{required_contract_path}` and must stay compatible with the provider contract.\n- Boundary input is translated into the required domain command before domain delegation.\n\nCommand/tool:\n\n- `rms compose --root <system-root>` compares required and provided capability contracts.\n- `rms verify implementation.yaml` exercises parser/delegation evidence when a binding exists.\n\nExpected result:\n\n- Required capability `{required_command}` resolves to provider `{provider}` with the same contract reference.\n- Malformed boundary input stops before domain delegation.\n- Accepted boundary input produces an enveloped domain command compatible with `{required_command}`.\n\nSource revision: recorded by git commit or strict audit provenance before production use.\n",
        required_command = markdown_inline(required_command),
        module = markdown_inline(module_name),
        provider = markdown_inline(provider_module),
        required_contract_path = markdown_inline(required_contract_path),
    )
}

fn render_composed_capability_evidence(
    name: &str,
    public_command: &str,
    domain_child: &str,
    boundary_child: &str,
) -> String {
    format!(
        "# Scenario Evidence: composed capability\n\nPromise:\n\n- Invariant `public-command-is-child-backed` holds for composite parent `{}`.\n- The parent exports `{}` through internal boundary child `{}`.\n- The boundary child depends on internal domain child `{}` for pure decisions.\n\nEvidence:\n\n- `rms compose --root <system-root>` verifies containment, internal visibility, and parent export backing.\n- `rms verify <this module.yaml>` rolls up composition and child implementation verification when child bindings exist.\n\nSource revision: recorded by the verifier or conformance report at runtime.\n",
        markdown_inline(name),
        markdown_inline(public_command),
        markdown_inline(boundary_child),
        markdown_inline(domain_child),
    )
}

fn contract_file_stem(name: &str) -> String {
    semantic_id_segment(name)
}

fn render_profile_sections(profiles: &[String]) -> String {
    let mut sections = String::new();
    let workflow = profiles.iter().any(|profile| profile == "workflow");
    if workflow || profiles.iter().any(|profile| profile == "stateful") {
        sections.push_str("\nstate: {}\n");
    }
    if workflow || profiles.iter().any(|profile| profile == "distributed") {
        sections.push_str("\noperations:\n  reconciliation: []\n");
    }
    if workflow {
        sections.push_str("\nworkflow: {}\n");
    }
    if profiles.iter().any(|profile| profile == "boundary") {
        sections.push_str("\nboundary: {}\n");
    }
    if profiles.iter().any(|profile| profile == "monitor") {
        sections.push_str("\nmonitor:\n  authority: observe-only\n  inputs: []\n  derived: []\n  triggers: []\n  failure_mode: fail-open\n");
    }
    sections
}

fn render_module_readme(
    name: &str,
    purpose: &str,
    kind: &str,
    profiles: &[String],
    binding: Option<&str>,
    shape: ScaffoldShape,
) -> String {
    let profile_lines = profiles
        .iter()
        .map(|profile| format!("- `{}`", markdown_inline(profile)))
        .collect::<Vec<_>>()
        .join("\n");
    let binding_line = match binding {
        Some(binding) => format!(
            "Implementation binding: `{}` via `implementation.yaml`.",
            markdown_inline(binding)
        ),
        None => "Implementation binding: none generated yet.".to_string(),
    };

    format!(
        "# {}\n\nPurpose: {}\nKind: `{}`\n{}\n\n## Profiles\n\n{}\n\n## Semantic Shape\n\nShape: `{}`: `{}` ({})\n\nRequired roles:\n{}\n\nRepresentation is the RMS-level role for closed variants, validated values, commands, states, events, and result/rejection types. Implement it with language-idiomatic files or modules; do not treat a folder named `domain` or `types` as canonical architecture. Traceable-machine roles make debugging bad states explicit: message envelopes carry identity and causality, transitions return next state plus emitted events, commands, effects, and reply, transition records capture before/after/input/output/source provenance, journals explain, replay bundles reproduce, and first-bad-transition evidence points to the fix. Use domain-named role suffixes where the language allows it: `<Domain>Machine`, `<Domain>State`, `<Domain>Command`, `<Domain>Event`, `<Domain>Effect`, `<Domain>EffectResult`, `<Domain>Reply`, `<Domain>Rejection`, `<Domain>Transition`, and `<Domain>TransitionRecord`. Do not derive inner role names from role or surface suffixes such as rules, engine, adapter, cli, web, rust, swift, or js unless those words are genuine domain language.\n\n## Representation Decisions\n\n- Closed domain alternatives should use ADTs, sealed variants, enums, or tagged constructors.\n- Public values with validity rules should use private fields, validated constructors, explicit failure types, semantic-function bindings, and evidence.\n- Validated numeric values should use checked, saturating, bounded, or explicitly proven arithmetic, with evidence for overflow, floors, ceilings, and rounding when arithmetic affects decisions.\n- Expected domain failures should be explicit result or rejection values rather than ambient exceptions.\n- Lifecycle or order-dependent behavior should use a transition model with accepted and rejected outcomes, transition records, replay bundles, and first-bad-transition diagnostics when applicable.\n- Boundary input should be parsed into enveloped domain commands before reaching pure decisions.\n- Runnable surfaces adapt outside input into declared RMS commands, may render or execute declared boundary effects, and must not reimplement domain decisions or call private module internals.\n- Public read models or result structs produced only by queries/projectors may keep private fields without public constructors only when `implementation.yaml` declares them in `architecture.allowed_missing_constructors` and evidence names the producing query/projector.\n- Projections observe and derive timelines; they do not emit workflow commands or mutate another module's state.\n- Do not add a fake public constructor only to satisfy a binding check; either expose a real contract-backed constructor or document the query-produced exception.\n\n## Runtime Monitor Decisions\n\n- Use this section when the module declares the `monitor` profile or `runtime-monitor` shape.\n- Declare observed inputs, derived facts or streams, trigger conditions, monitor authority, retrigger/idempotency policy, and fail-open/fail-closed/degraded behavior in `module.yaml`.\n- Supervisory outputs must be public commands, events, alarms, findings, or capabilities. Do not mutate controlled module state directly.\n- Add runtime evidence for trigger and non-trigger cases before relying on a monitor for release or operational assurance.\n\n## Canonical Artifacts\n\n- `module.yaml` is the source of module ownership, public surface, dependencies, effects, invariants, profiles, and compatibility.\n- `contracts/` contains public RMS contracts only: commands, queries, events, APIs, capabilities, schemas, and externally consumed failure semantics.\n- `implementation.yaml`, when present, binds code symbols to contracts, invariants, assumptions, and evidence.\n- `verification/` contains evidence for declared promises. Evidence should name the source revision and command or tool used.\n\n## Before Changing Behavior\n\n1. Fill `module.yaml` with owned concepts, data, decisions, public surface, dependencies, effects, invariants, and verification references that are true for this module.\n2. Add or update public contracts before implementing externally consumed behavior.\n3. Keep private implementation details out of `contracts/` unless consumers depend on them.\n4. Add the smallest evidence that proves the declared promise, including negative cases for invalid inputs, illegal transitions, replayed bad states, numeric boundary cases, or passive projections when applicable.\n5. Use `rms spec apply module.yaml --change-yaml '<semantic-change>'` when new laws, contracts, states, commands, events, effects, effect results, replies, rejections, transitions, semantic roles, runnable surfaces, public entrypoints, or evidence obligations are needed; then fill declared role bodies.\n6. Use `rms surface apply implementation.yaml --kind runnable-boundary --surface <surface> --entrypoint <path> --delegates-to <role-or-symbol> --command <public-command>` before adding or changing app, UI, CLI, browser, HTTP, batch, mobile, desktop, or executable entrypoints.\n7. Use `rms machine apply implementation.yaml --change-yaml '<machine-change>'` only for focused inner-machine edits after laws, public contracts, and evidence obligations are already correct.\n8. Run `rms validate --root <system-root>` and `rms compose --root <system-root>`; run `rms spec check module.yaml`, `rms machine check implementation.yaml`, `rms surface check implementation.yaml`, `rms structure implementation.yaml`, and `rms verify implementation.yaml` when an implementation binding exists.\n9. Replace scaffold placeholder evidence before declaring this module implemented; `rms validate --root <system-root>` should not report placeholder, bootstrap, unpinned, or semantic-shape-only evidence for implemented promises.\n\n## Agent Workflow\n\nUse `rms design --root <system-root> --task \"<task>\"` when module boundaries or semantic shapes are unclear. Use `rms explain module.yaml` and `rms context module.yaml --task \"<task>\"` before implementation work. Use `rms spec plan module.yaml --task \"<task>\"` before changing product meaning, laws, contracts, runnable surfaces, effects, machine structure, or evidence obligations. Use `rms surface apply/check implementation.yaml` before app/UI/CLI/browser/HTTP/batch/mobile/desktop/executable entrypoint changes. Use `rms machine plan implementation.yaml --task \"<task>\"` only for focused inner-machine edits after the semantic layer is correct. Use `rms evolve-contract module.yaml --task \"<task>\"` when public compatibility requires deeper guidance, and `rms evidence module.yaml --task \"<task>\"` when proof design is unclear.\n",
        markdown_inline(name),
        markdown_inline(purpose),
        markdown_inline(kind),
        binding_line,
        profile_lines,
        shape.title(),
        shape.as_str(),
        shape.purpose(),
        shape
            .roles()
            .iter()
            .map(|role| format!("- `{}`", markdown_inline(role)))
            .collect::<Vec<_>>()
            .join("\n")
    )
}

fn render_contracts_readme() -> String {
    "# Contracts\n\nPlace public RMS contract files here.\n\nA contract belongs here when consumers outside this module can call, observe, depend on, or substitute against the behavior. Private helpers stay in implementation docs and tests.\n\nWhen adding or changing a contract:\n\n1. Declare it from `module.yaml`.\n2. Specify preconditions, postconditions, failure categories, and compatibility policy.\n3. Bind implemented symbols from `implementation.yaml` when code provides the behavior.\n4. Add matching evidence under `verification/contracts/`.\n".to_string()
}

fn render_traceable_architecture_yaml(
    names: &InnerStructureNames,
    shape: ScaffoldShape,
    transition_source_path: &str,
) -> String {
    let mut out = String::new();
    let mut public_field_structs = vec![
        names.command_envelope.as_str(),
        names.event_envelope.as_str(),
        names.transition.as_str(),
        names.transition_record.as_str(),
        names.source_provenance.as_str(),
    ];
    if scaffold_declares_effects_by_default(shape) {
        public_field_structs.push(names.effect_envelope.as_str());
    }
    if scaffold_declares_effect_results_by_default(shape) {
        public_field_structs.push(names.effect_result_envelope.as_str());
    }
    let _ = writeln!(out, "  allowed_public_field_structs:");
    for item in public_field_structs {
        let _ = writeln!(out, "    - {}", yaml_quote(item));
    }
    let _ = writeln!(out, "  messages:");
    let _ = writeln!(out, "    command_envelope:");
    for field in [
        "command_id",
        "target_machine",
        "correlation_id",
        "causation_id",
        "idempotency_key",
    ] {
        let _ = writeln!(out, "      - {field}");
    }
    let _ = writeln!(out, "    event_envelope:");
    for field in [
        "event_id",
        "source_machine",
        "correlation_id",
        "causation_id",
        "sequence",
        "schema_version",
        "occurred_at",
    ] {
        let _ = writeln!(out, "      - {field}");
    }
    if scaffold_declares_effects_by_default(shape) {
        let _ = writeln!(out, "    effect_envelope:");
        for field in [
            "effect_id",
            "requester",
            "correlation_id",
            "causation_id",
            "idempotency_key",
        ] {
            let _ = writeln!(out, "      - {field}");
        }
    }
    if scaffold_declares_effect_results_by_default(shape) {
        let _ = writeln!(out, "    effect_result_envelope:");
        for field in [
            "effect_id",
            "requester",
            "correlation_id",
            "causation_id",
            "status",
        ] {
            let _ = writeln!(out, "      - {field}");
        }
    }
    if shape == ScaffoldShape::Workflow {
        let _ = writeln!(out, "    subscriptions:");
        let _ = writeln!(out, "      - workflow-inputs");
    }
    let _ = writeln!(out, "  transition:");
    let _ = writeln!(out, "    output:");
    for field in [
        "next_state",
        "events",
        "commands",
        "effects",
        "reply",
        "rejection",
    ] {
        let _ = writeln!(out, "      - {field}");
    }
    if scaffold_declares_effects_by_default(shape) && idempotency_expected_for_shape(shape.as_str())
    {
        let _ = writeln!(out, "  effects:");
        let _ = writeln!(out, "    idempotency_keys:");
        let _ = writeln!(out, "      - effect_id");
    }
    let _ = writeln!(out, "  numeric_safety:");
    let _ = writeln!(
        out,
        "    validated_arithmetic: checked-or-bounded-or-proven"
    );
    let _ = writeln!(out, "  trace:");
    let _ = writeln!(out, "    journal: transition-records");
    let _ = writeln!(out, "    timeline_projection: transition-records");
    let _ = writeln!(out, "    replay_bundle: transition-records");
    let _ = writeln!(
        out,
        "    first_bad_transition: source-provenance-from-transition-record"
    );
    let producer = scaffold_trace_producer_reference(transition_source_path);
    let _ = writeln!(out, "    producers:");
    for bundle in scaffold_trace_bundle_files(shape) {
        let _ = writeln!(
            out,
            "      - id: {}-{}",
            names.prefix,
            semantic_id_segment(bundle.trim_end_matches(".yaml"))
        );
        let _ = writeln!(out, "        profile: smoke");
        let _ = writeln!(out, "        bundle: verification/traces/{bundle}");
        let _ = writeln!(out, "        command: trace");
        let _ = writeln!(out, "        runner: {producer}");
    }
    if property_evidence_expected_for_shape(shape) || fuzz_evidence_expected_for_shape(shape) {
        let _ = writeln!(out, "  reliability:");
        if property_evidence_expected_for_shape(shape) {
            let _ = writeln!(out, "    properties:");
            let _ = writeln!(
                out,
                "      - id: {}-transition-output-is-declared",
                names.prefix
            );
            let _ = writeln!(out, "        proves: transition-trace");
            let _ = writeln!(
                out,
                "        input_space: generated valid and rejected commands"
            );
            let _ = writeln!(out, "        oracle:");
            let _ = writeln!(out, "          - transition outputs use declared variants");
            let _ = writeln!(
                out,
                "          - replay records preserve source branch and state movement"
            );
            let _ = writeln!(out, "        command: properties");
            let _ = writeln!(
                out,
                "        evidence: verification/properties/transition_properties.md"
            );
            let _ = writeln!(
                out,
                "        counterexamples: verification/fuzz/counterexamples"
            );
            let _ = writeln!(out, "        realizations:");
            let _ = writeln!(out, "          - profile: smoke");
            let _ = writeln!(out, "            strategy: generated-property");
            let _ = writeln!(out, "            command: properties");
            let _ = writeln!(
                out,
                "            generator: {}#generate_property_cases",
                transition_source_path
            );
            let _ = writeln!(
                out,
                "            runner: {}",
                scaffold_property_runner_reference(transition_source_path, false)
            );
        }
        if fuzz_evidence_expected_for_shape(shape) {
            let _ = writeln!(out, "    fuzz_targets:");
            let _ = writeln!(
                out,
                "      - id: {}-malformed-input-stops-before-domain",
                names.prefix
            );
            let _ = writeln!(out, "        proves: malformed-input-stops-before-domain");
            let _ = writeln!(out, "        input_space: generated raw boundary inputs");
            let _ = writeln!(out, "        oracle:");
            let _ = writeln!(out, "          - malformed input returns typed rejection");
            let _ = writeln!(
                out,
                "          - rejected input emits no delegated domain command"
            );
            let _ = writeln!(out, "        command: fuzz");
            let _ = writeln!(
                out,
                "        evidence: verification/fuzz/malformed_input_fuzz.md"
            );
            let _ = writeln!(
                out,
                "        counterexamples: verification/fuzz/counterexamples"
            );
            let _ = writeln!(out, "        realizations:");
            let _ = writeln!(out, "          - profile: smoke");
            let _ = writeln!(out, "            strategy: generated-property");
            let _ = writeln!(out, "            command: fuzz");
            let _ = writeln!(
                out,
                "            generator: {}#generate_malformed_input_cases",
                transition_source_path
            );
            let _ = writeln!(
                out,
                "            runner: {}",
                scaffold_property_runner_reference(transition_source_path, true)
            );
        }
    }
    out
}

fn scaffold_trace_bundle_files(shape: ScaffoldShape) -> Vec<&'static str> {
    match shape {
        ScaffoldShape::DomainEngine | ScaffoldShape::Workflow => vec!["transition_trace.yaml"],
        ScaffoldShape::BoundaryAdapter
        | ScaffoldShape::StorageAdapter
        | ScaffoldShape::IntegrationAdapter => {
            vec!["boundary_parse.yaml", "malformed_input_trace.yaml"]
        }
        ScaffoldShape::RuntimeMonitor | ScaffoldShape::Composite => Vec::new(),
    }
}

fn scaffold_trace_producer_reference(transition_source_path: &str) -> String {
    if transition_source_path.ends_with(".rs") {
        "tests/trace_producer.rs#produce_transition_trace".to_string()
    } else if transition_source_path.ends_with(".mjs") {
        "tests/trace-producer.mjs#produceTransitionTrace".to_string()
    } else if transition_source_path.ends_with(".swift") {
        let target = Path::new(transition_source_path)
            .components()
            .nth(1)
            .and_then(|component| match component {
                Component::Normal(value) => value.to_str(),
                _ => None,
            })
            .unwrap_or("Module");
        format!("Tests/{target}Tests/{target}Tests.swift#testProduceTransitionTrace")
    } else {
        "scripts/trace.sh#produce_transition_trace".to_string()
    }
}

fn scaffold_property_runner_reference(transition_source_path: &str, malformed: bool) -> String {
    if transition_source_path.ends_with(".rs") {
        format!(
            "src/lib.rs#{}",
            if malformed {
                "fuzz_malformed_generated_values_are_rejected_by_constructor"
            } else {
                "property_transition_outputs_use_declared_variants"
            }
        )
    } else if transition_source_path.ends_with(".mjs") {
        format!(
            "tests/{}#{}",
            if malformed {
                "boundary-smoke.mjs"
            } else {
                "trace-smoke.mjs"
            },
            if malformed {
                "runMalformedInputProperty"
            } else {
                "runTransitionProperty"
            }
        )
    } else if transition_source_path.ends_with(".swift") {
        let target = Path::new(transition_source_path)
            .components()
            .nth(1)
            .and_then(|component| match component {
                Component::Normal(value) => value.to_str(),
                _ => None,
            })
            .unwrap_or("Module");
        format!(
            "Tests/{target}Tests/{target}Tests.swift#{}",
            if malformed {
                "testFuzzMalformedGeneratedValuesAreRejectedByConstructor"
            } else {
                "testPropertyTransitionOutputsUseDeclaredVariants"
            }
        )
    } else {
        "scripts/smoke.sh#run_property".to_string()
    }
}

fn render_traceable_roles_yaml(
    shape: ScaffoldShape,
    representation_path: &str,
    transition_path: &str,
) -> String {
    render_traceable_roles_yaml_with_parser(
        shape,
        representation_path,
        transition_path,
        transition_path,
    )
}

fn render_traceable_roles_yaml_with_parser(
    shape: ScaffoldShape,
    representation_path: &str,
    transition_path: &str,
    parser_path: &str,
) -> String {
    let mut out = String::new();
    let trace_evidence_path = if parser_expected_for_shape(shape.as_str()) {
        "verification/boundaries/malformed_input.md"
    } else {
        "verification/laws/transition_trace.md"
    };
    for (role, path) in [
        ("representation", representation_path),
        ("transition", transition_path),
        ("message_envelope", representation_path),
        ("transition_record", transition_path),
        ("journal", transition_path),
        ("timeline_projection", transition_path),
    ] {
        let _ = writeln!(out, "    {role}:");
        let _ = writeln!(out, "      - {path}");
    }
    if !scaffold_trace_bundle_files(shape).is_empty() {
        let producer = scaffold_trace_producer_reference(transition_path);
        let producer_path = binding_reference_parts(&producer)
            .map(|(path, _)| path)
            .unwrap_or(producer.as_str());
        let _ = writeln!(out, "    trace_producer:");
        let _ = writeln!(out, "      - {producer_path}");
    }
    if parser_expected_for_shape(shape.as_str()) {
        let _ = writeln!(out, "    parser:");
        let _ = writeln!(out, "      - {parser_path}");
    }
    if scaffold_declares_effects_by_default(shape) {
        let executor_path = binding_sibling_role_path(transition_path, "effect_executor");
        let _ = writeln!(out, "    effect_executor:");
        let _ = writeln!(out, "      - {executor_path}");
        if is_stateful_machine_mode(machine_mode_for_shape(shape)) {
            let driver_path = binding_sibling_role_path(transition_path, "machine_driver");
            let _ = writeln!(out, "    machine_driver:");
            let _ = writeln!(out, "      - {driver_path}");
        }
    }
    let _ = writeln!(out, "    replay_bundle:");
    let _ = writeln!(out, "      - {transition_path}");
    let _ = writeln!(out, "    trace_evidence:");
    let _ = writeln!(out, "      - {trace_evidence_path}");
    if shape == ScaffoldShape::Workflow {
        let _ = writeln!(out, "    subscription_registry:");
        let _ = writeln!(out, "      - {transition_path}");
    }
    if property_evidence_expected_for_shape(shape) {
        let _ = writeln!(out, "    property_generator:");
        let _ = writeln!(out, "      - {transition_path}");
        let _ = writeln!(out, "    property_oracle:");
        let _ = writeln!(out, "      - {transition_path}");
        let _ = writeln!(out, "    counterexample_replay:");
        let _ = writeln!(out, "      - {transition_path}");
    }
    if fuzz_evidence_expected_for_shape(shape) {
        let _ = writeln!(out, "    fuzz_target:");
        let _ = writeln!(out, "      - {parser_path}");
        let _ = writeln!(out, "    seed_corpus:");
        let _ = writeln!(out, "      - verification/fuzz");
        let _ = writeln!(out, "    counterexample_replay:");
        let _ = writeln!(out, "      - {parser_path}");
    }
    if matches!(
        shape,
        ScaffoldShape::StorageAdapter | ScaffoldShape::IntegrationAdapter
    ) {
        let _ = writeln!(out, "    inbox_outbox:");
        let _ = writeln!(out, "      - {representation_path}");
    }
    out
}

fn binding_sibling_role_path(source_path: &str, stem: &str) -> String {
    let path = Path::new(source_path);
    let extension = path.extension().and_then(|value| value.to_str());
    let file_name = match extension {
        Some("swift") => match stem {
            "effect_executor" => "EffectExecutor.swift".to_string(),
            "machine_driver" => "MachineDriver.swift".to_string(),
            _ => format!(
                "{}.swift",
                pascal_case_tokens(&identifier_word_tokens(stem))
            ),
        },
        Some(extension) => format!("{stem}.{extension}"),
        None => stem.to_string(),
    };
    path.parent()
        .map(|parent| parent.join(&file_name).display().to_string())
        .unwrap_or(file_name)
}

