    #[test]
    fn empty_verification_category_makes_conformance_partial() {
        let value: YamlValue = serde_yaml::from_str(
            r#"
verification:
  laws:
    - verification/laws
  contracts: []
  scenarios:
    - verification/scenarios
  boundaries: []
"#,
        )
        .unwrap();

        assert!(has_empty_verification_category(&value));
    }

    fn generate_malformed_artifact_cases() -> Vec<YamlValue> {
        let baseline: YamlValue = serde_yaml::from_str(
            r#"spec: rms/module/v0.1
module: { name: example, version: 0.1.0, kind: library, purpose: example }
profiles: [core]
owns: { concepts: [], data: [], decisions: [] }
provides: { commands: [], queries: [], events: [], capabilities: [] }
requires: { modules: [], capabilities: [] }
invariants: []
effects: []
compatibility: { policy: backward-compatible-within-major }
verification: { laws: [], contracts: [], scenarios: [], boundaries: [] }
"#,
        )
        .unwrap();
        let required_paths: &[&[&str]] = &[
            &["spec"],
            &["module"],
            &["profiles"],
            &["owns"],
            &["provides"],
            &["requires"],
            &["compatibility"],
            &["verification"],
        ];
        let mut cases = Vec::new();
        for (path_index, path) in required_paths.iter().enumerate() {
            let malformed_values = if *path == ["profiles"] {
                vec![
                    YamlValue::Null,
                    YamlValue::Bool(false),
                    YamlValue::Number(serde_yaml::Number::from(-1)),
                    YamlValue::Mapping(serde_yaml::Mapping::new()),
                ]
            } else {
                vec![
                    YamlValue::Null,
                    YamlValue::Bool(false),
                    YamlValue::Number(serde_yaml::Number::from(-1)),
                    YamlValue::Sequence(Vec::new()),
                ]
            };
            for (value_index, value) in malformed_values.iter().enumerate() {
                let mut candidate = baseline.clone();
                set_yaml_value_path(&mut candidate, path, value.clone());
                if (path_index + value_index) % 2 == 0 {
                    set_yaml_string_path(
                        &mut candidate,
                        &["module", "name"],
                        &format!("generated-invalid-{path_index}-{value_index}"),
                    );
                }
                cases.push(candidate);
            }
        }
        cases
    }

    #[test]
    fn schema_validation_reports_shape_errors() {
        for value in generate_malformed_artifact_cases() {
            let manifest = LoadedManifest {
                path: PathBuf::from("module.yaml"),
                value,
            };
            let mut diagnostics = Vec::new();

            validate_loaded_manifest(&manifest, &mut diagnostics);

            assert!(
                !diagnostics.is_empty(),
                "generated case was accepted without a diagnostic: {:#?}",
                manifest.value
            );
        }
    }

    #[test]
    fn implementation_schema_rejects_legacy_machine_fields() {
        let canonical = r#"
spec: rms/implementation/v0.1
module: example
binding: js
source:
  root: .
  public_entrypoint: src/transition.mjs
commands:
  build: node --check src/transition.mjs
  verify: node --check src/transition.mjs
architecture:
  shape: domain-engine
  machine:
    name: ExampleMachine
    mode: stateless-decision-machine
    transition_signature: input-only
    stateless_justification: The decision has no lifecycle.
    types:
      state: ExampleState
      command: ExampleCommand
      event: ExampleEvent
      reply: ExampleReply
      rejection: ExampleRejection
      transition: ExampleTransition
      transition_record: ExampleTransitionRecord
    states: [Ready]
    commands: [Accept]
    observed_events: []
    events: [Accepted]
    effects: []
    effect_results: []
    replies: [Accepted]
    rejections: [Rejected]
    effect_protocols: []
    transition_function: transition
    transitions:
      - from: Ready
        on: Accept
        to: Ready
        events: [Accepted]
        reply: Accepted
  roles:
    representation: [src/representation.mjs]
    transition: [src/transition.mjs]
"#;

        let canonical_manifest = LoadedManifest {
            path: PathBuf::from("implementation.yaml"),
            value: serde_yaml::from_str(canonical).unwrap(),
        };
        let mut canonical_diagnostics = Vec::new();
        validate_against_embedded_schema(&canonical_manifest, &mut canonical_diagnostics);
        assert!(
            canonical_diagnostics.is_empty(),
            "{canonical_diagnostics:#?}"
        );

        for source in [
            canonical.replace(
                "    states: [Ready]",
                "    state: ExampleState\n    states: [Ready]",
            ),
            canonical.replace("  machine:\n", "  state_type: ExampleState\n  machine:\n"),
        ] {
            let manifest = LoadedManifest {
                path: PathBuf::from("implementation.yaml"),
                value: serde_yaml::from_str(&source).unwrap(),
            };
            let mut diagnostics = Vec::new();
            validate_against_embedded_schema(&manifest, &mut diagnostics);
            assert!(
                diagnostics
                    .iter()
                    .any(|diagnostic| diagnostic.check == "schema.validate"),
                "legacy machine declaration unexpectedly validated"
            );
        }
    }

