    fn write_package_fixture(root: &Path) {
        fs::create_dir_all(root.join("contracts")).unwrap();
        fs::create_dir_all(root.join("scripts")).unwrap();
        fs::create_dir_all(root.join("src")).unwrap();
        fs::create_dir_all(root.join("verification/laws")).unwrap();
        fs::create_dir_all(root.join("verification/traces")).unwrap();
        fs::write(
            root.join("contracts/do-work.yaml"),
            "spec: rms/contract/v0.1\nname: do-work\nkind: command\nmeaning: Do work.\n",
        )
        .unwrap();
        fs::write(root.join("verification/laws/law"), "law evidence\n").unwrap();
        fs::write(
            root.join("verification/traces/transition_trace.yaml"),
            "spec: rms/trace-bundle/v0.1\nmachine: PackageFixtureMachine\nrecords: []\n",
        )
        .unwrap();
        fs::write(
            root.join("scripts/build.sh"),
            "#!/usr/bin/env sh\nset -eu\n",
        )
        .unwrap();
        fs::write(
            root.join("scripts/smoke.sh"),
            "#!/usr/bin/env sh\nset -eu\n",
        )
        .unwrap();
        fs::write(root.join("src/public.mjs"), "export * from './representation.mjs';\nexport { transition, transitionRecord, PackageFixtureMachine } from './transition.mjs';\n").unwrap();
        fs::write(
            root.join("src/representation.mjs"),
            r#"export const Ready = Object.freeze({ tag: "PackageFixtureState.Ready" });
export const PackageFixtureState = Object.freeze({ Ready });
export const PackageFixtureCommand = Object.freeze({ Accept: "PackageFixtureCommand.Accept" });
export const PackageFixtureEvent = Object.freeze({ Accepted: "PackageFixtureEvent.Accepted" });
export const PackageFixtureReply = Object.freeze({ Accepted: "PackageFixtureReply.Accepted" });
export const PackageFixtureRejection = Object.freeze({ InvalidCommand: "PackageFixtureRejection.InvalidCommand" });
"#,
        )
        .unwrap();
        fs::write(
            root.join("src/transition.mjs"),
            r#"export function transition(command) {
  return {
    next_state: { tag: "PackageFixtureState.Ready" },
    events: [{ tag: "PackageFixtureEvent.Accepted" }],
    commands: [],
    effects: [],
    reply: { tag: "PackageFixtureReply.Accepted", command },
  };
}
export function transitionRecord(command) {
  return {
    state_before: { tag: "PackageFixtureState.Ready" },
    state_after: { tag: "PackageFixtureState.Ready" },
    input: command,
    output: transition(command),
  };
}
export const PackageFixtureTransition = Object.freeze({ create: transition });
export const PackageFixtureTransitionRecord = Object.freeze({ create: transitionRecord });
export const PackageFixtureMachine = Object.freeze({ transition, transitionRecord });
"#,
        )
        .unwrap();
        fs::write(
            root.join("implementation.yaml"),
            r#"spec: rms/implementation/v0.1
module: package-fixture
binding: js
source:
  root: .
  public_entrypoint: src/public.mjs
commands:
  build: sh scripts/build.sh
  verify: sh scripts/smoke.sh
distribution:
  reusable: true
  public_facade: src/public.mjs
architecture:
  shape: domain-engine
  public_modules:
    - src/public.mjs
    - src/representation.mjs
    - src/transition.mjs
  machine:
    name: PackageFixtureMachine
    mode: stateless-decision-machine
    transition_signature: input-only
    stateless_justification: fixture has no lifecycle state
    types:
      state: PackageFixtureState
      command: PackageFixtureCommand
      event: PackageFixtureEvent
      reply: PackageFixtureReply
      rejection: PackageFixtureRejection
      transition: PackageFixtureTransition
      transition_record: PackageFixtureTransitionRecord
    states: [Ready]
    commands: [Accept]
    observed_events: []
    events: [Accepted]
    effects: []
    effect_results: []
    replies: [Accepted]
    rejections: [InvalidCommand]
    effect_protocols: []
    transition_function: transition
    transitions:
      - from: Ready
        on: Accept
        to: Ready
        events: [Accepted]
        reply: Accepted
  roles:
    representation: [src/representation.mjs]
    transition: [src/transition.mjs]
    replay_bundle: [verification/traces/transition_trace.yaml]
    trace_evidence: [verification/traces/transition_trace.yaml]
semantic_functions:
  - id: transition-model
    symbol: src/transition.mjs#transition
    kind: transition
    purity: pure
"#,
        )
        .unwrap();
        fs::write(
            root.join("module.yaml"),
            r#"spec: rms/module/v0.1

module:
  name: package-fixture
  version: 0.1.0
  kind: library
  purpose: Test packaging

profiles:
  - core

owns:
  concepts: []
  data: []
  decisions: []

provides:
  commands:
    - name: do-work
      contract: contracts/do-work.yaml
  queries: []
  events: []
  capabilities: []

requires:
  modules: []
  capabilities: []

invariants:
  - id: law
    statement: Law holds.
    authority: transition
    enforced_by: transition-model
    verified_by: verification/laws/law

effects: []

boundary:
  validation: reject-before-domain-entry

compatibility:
  policy: backward-compatible-within-major

verification:
  laws:
    - verification/laws
  contracts: []
  scenarios: []
  boundaries: []
  traces:
    - verification/traces
"#,
        )
        .unwrap();
    }

    #[test]
    fn module_atlas_derives_stable_nodes_from_manifest() {
        let root = atlas_fixture("atlas-graph");
        let manifest = load_manifest(&root.join("module.yaml")).unwrap();

        let atlas = build_module_atlas(&manifest, &root).unwrap();

        fs::remove_dir_all(&root).unwrap();
        assert_eq!(atlas.spec, "rms/atlas/v0.1");
        assert_eq!(atlas.module.id, "module:atlas-fixture");
        assert!(atlas.interaction.supports_live_reconciliation);
        assert!(atlas.nodes.iter().any(|node| {
            node.id == "provides-commands:do-work"
                && node.layer == "public-surface"
                && node
                    .source_refs
                    .iter()
                    .any(|reference| reference.path == "contracts/do-work.v1.yaml")
        }));
        assert!(atlas
            .nodes
            .iter()
            .any(|node| node.id == "invariant:work-is-safe"));
        assert!(atlas.edges.iter().any(|edge| {
            edge.kind == "verifies"
                && edge.from == "verification:verification-laws-work-is-safe"
                && edge.to == "invariant:work-is-safe"
        }));
        let trace = atlas
            .traces
            .iter()
            .find(|trace| trace.id == "trace:do-work")
            .expect("do-work trace");
        assert_eq!(trace.entry_node_id, "provides-commands:do-work");
        let rule_step = trace
            .steps
            .iter()
            .find(|step| {
                step.role == "Rule"
                    && step.confidence == "inferred"
                    && step
                        .node_ids
                        .contains(&"invariant:work-is-safe".to_string())
            })
            .expect("rule trace step");
        assert_eq!(
            rule_step.reading.impact,
            "Changing this stage can weaken or move domain authority."
        );
        assert!(trace
            .gaps
            .iter()
            .any(|gap| gap.id == "effect" && gap.suggested_artifact.is_some()));
        assert!(atlas
            .tours
            .first()
            .is_some_and(|tour| !tour.steps.is_empty()));
    }

